using System.Collections;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RuinEffect", menuName = "Data/Battle/Effects/Enemy/Ruin Effect")]
public class RuinEffect : Effect
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		string localizedAtTheStartOfItsTurn = base.localizationManager.GetLocalizedAtTheStartOfItsTurn();
		string localizedEffectOwnerReceiveFormatted = base.localizationManager.GetLocalizedEffectOwnerReceiveFormatted(purify: false, amount);
		return base.localizationManager.GetLocalizedConditionActivationThenDecreaseFormatFormatted(localizedAtTheStartOfItsTurn, localizedEffectOwnerReceiveFormatted.RemoveLast(), this, 1);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueNefariousPulseDischargeRuinAction(RuinCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator RuinCoroutine(int effectAmount, GameObject effectOwner)
	{
		if (currentCorruptedAnimals.IsAnyEnemyActive())
		{
			UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
			unitEffects.IsEffectActive(this);
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 3f);
			if (IsVFXEnabled())
			{
				PlayEffectActivationSFX();
			}
			yield return new WaitForSeconds(0.7f);
			effectOwner.GetComponent<CorruptionStats>().Corrupt(effectAmount, null);
			yield return new WaitForSeconds(0.3f);
			unitEffects.IsEffectActiveAndDecreaseEffect(this, 1);
			yield return new WaitForSeconds(0.6f);
		}
	}
}
